  1	// tcgen05 (sm_100 5th-gen tensor-core) PRIMITIVES.
  2	//
  3	// THE STRUCTURAL THESIS (confirmed by profiling): the n=512 _trailing_fused_
  4	// kernel is REGISTER-WALLED (221 reg/thr -> 4 blocks/SM, 11.7% occupancy)
  5	// because Triton's tl.dot accumulates the multi-pass MMA in REGISTERS. tcgen05's
  6	// mma accumulates the result in TMEM (dedicated tensor memory, NOT registers) ->
  7	// structurally escapes the register wall. These primitives are the substrate;
  8	// the trailing-GEMM kernels below consume them.
  9	//
 10	// All inline-PTX is verified on this B200 (sm_100a) through NVRTC 12.8. The
 11	// minimal fp16->fp32 GEMM (tcgen05_selftest below) is bit-exact-to-fp16 vs a
 12	// reference matmul. References:
 13	//   https://gau-nernst.github.io/tcgen05/  (canonical minimal example)
 14	//   PTX ISA 9.7.17 (tcgen05 instructions, descriptors, canonical layouts)
 15	// ---------------------------------------------------------------------------
 16	
 17	// fp32 -> fp16 bits (round-to-nearest), header-free.
 18	__device__ __forceinline__ ushort _f2h(float x){
 19	  ushort h; asm volatile("cvt.rn.f16.f32 %0, %1;" : "=h"(h) : "f"(x)); return h;
 20	}
 21	
 22	// elect a single leader lane in a warp (CUTLASS cluster_sm90 idiom).
 23	__device__ __forceinline__ uint32_t _elect_one(){
 24	  uint32_t pred = 0;
 25	  asm volatile("{\n\t.reg .pred %%px;\n\telect.sync _|%%px, %1;\n\t"
 26	               "@%%px mov.s32 %0, 1;\n\t}" : "+r"(pred) : "r"(0xFFFFFFFF));
 27	  return pred;
 28	}
 29	
 30	// 64-bit shared-memory matrix descriptor, no-swizzle, K-major "contiguous
 31	// blocks of (height, 8)" layout. LBO/SBO per PTX canonical layouts.
 32	__device__ __forceinline__ uint64_t _desc_enc(uint64_t x){ return (x & 0x3FFFFULL) >> 4ULL; }
 33	__device__ __forceinline__ uint64_t _smem_desc(int addr, int height){
 34	  const int LBO = height * 16, SBO = 8 * 16;     // bytes
 35	  return _desc_enc((uint64_t)addr) | (_desc_enc(LBO) << 16ULL)
 36	       | (_desc_enc(SBO) << 32ULL) | (1ULL << 46ULL);
 37	}
 38	
 39	// mbarrier helpers (single-CTA, parity-phase wait).
 40	__device__ __forceinline__ void _mbar_init(int mbar, int count){
 41	  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(mbar), "r"(count));
 42	  asm volatile("fence.mbarrier_init.release.cluster;");
 43	}
 44	__device__ __forceinline__ void _mbar_wait(int mbar, int phase){
 45	  uint32_t ticks = 0x989680;
 46	  asm volatile("{\n\t.reg .pred P1;\n\tLAB_W:\n\t"
 47	               "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 P1, [%0], %1, %2;\n\t"
 48	               "@P1 bra.uni LAB_D;\n\tbra.uni LAB_W;\n\tLAB_D:\n\t}"
 49	               :: "r"(mbar), "r"(phase), "r"(ticks));
 50	}
 51	
 52	// tcgen05 ops (cta_group::1).
 53	__device__ __forceinline__ void _tc_alloc(int smem_addr, int ncols){
 54	  asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;"
 55	               :: "r"(smem_addr), "r"(ncols));
 56	}
 57	__device__ __forceinline__ void _tc_dealloc(int taddr, int ncols){
 58	  asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;"
 59	               :: "r"(taddr), "r"(ncols));
 60	}
 61	__device__ __forceinline__ void _tc_relinquish(){
 62	  asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
 63	}
 64	// one fp16 MMA atom (M from idesc, N from idesc, K=16). enable_d != 0 accumulates.
 65	__device__ __forceinline__ void _tc_mma_f16(int taddr, uint64_t a_desc, uint64_t b_desc,
 66	                                            uint32_t i_desc, int enable_d){
 67	  asm volatile("{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %4, 0;\n\t"
 68	               "tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, p;\n\t}"
 69	               :: "r"(taddr), "l"(a_desc), "l"(b_desc), "r"(i_desc), "r"(enable_d));
 70	}
 71	__device__ __forceinline__ void _tc_commit(int mbar){
 72	  asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];"
 73	               :: "r"(mbar) : "memory");
 74	}
 75	__device__ __forceinline__ void _tc_fence(){ asm volatile("tcgen05.fence::after_thread_sync;"); }
 76	
 77	// instruction descriptor for fp16 A/B, fp32 accumulate. M = MMA_M (64 or 128),
 78	// N = MMA_N (mult of 8). a_format=0(f16) b_format=0(f16) c_format=1(f32).
 79	__device__ __forceinline__ uint32_t _idesc_f16(int M, int N){
 80	  return (1U << 4U) | ((uint32_t)N >> 3U << 17U) | ((uint32_t)M >> 4U << 24U);
 81	}
