 83	// ---------------------------------------------------------------------------
 84	// tcgen05_selftest: minimal correctness probe baked into the module. Computes
 85	// C[M,N] = A[M,K] @ B[N,K]^T (one fp16 MMA atom: M=128, N<=256, K=16) with the
 86	// accumulator in TMEM. Used by the QR_TCGEN05_SELFTEST python path to prove the
 87	// tcgen05 stack works on the host box before any trailing kernel relies on it.
 88	// ---------------------------------------------------------------------------
 89	extern "C" __global__ void tcgen05_selftest(const float* A, const float* B, float* C,
 90	                                            int M, int N, int K){
 91	  const int BM = 128;                 // MMA_M
 92	  const int BN = N;                   // MMA_N (caller: N<=256, mult of 8)
 93	  const int BK = 16;                  // one atom
 94	  const int tid = threadIdx.x, warp_id = tid >> 5, lane = tid & 31;
 95	  extern __shared__ __align__(1024) char tc_smem[];
 96	  const int A_smem = (int)__cvta_generic_to_shared(tc_smem);
 97	  const int B_smem = A_smem + BM * BK * (int)sizeof(ushort);
 98	  ushort* As = reinterpret_cast<ushort*>(tc_smem);
 99	  ushort* Bs = reinterpret_cast<ushort*>(tc_smem + BM * BK * sizeof(ushort));
100	  #pragma nv_diag_suppress static_var_with_dynamic_init
101	  __shared__ uint64_t mbar[1];
102	  __shared__ int tmem[1];
103	  const int mbar_addr = (int)__cvta_generic_to_shared(mbar);
104	  for (int i = tid; i < BM * BK; i += blockDim.x){
105	    int r = i / BK, k = i % BK, b = k >> 3, kk = k & 7;
106	    As[b * (BM * 8) + r * 8 + kk] = _f2h(A[r * K + k]);
107	  }
108	  for (int i = tid; i < BN * BK; i += blockDim.x){
109	    int r = i / BK, k = i % BK, b = k >> 3, kk = k & 7;
110	    Bs[b * (BN * 8) + r * 8 + kk] = _f2h(B[r * K + k]);
111	  }
112	  __syncthreads();
113	  if (warp_id == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
114	  else if (warp_id == 1){ int a = (int)__cvta_generic_to_shared(tmem); _tc_alloc(a, BN); }
115	  __syncthreads();
116	  const int taddr = tmem[0];
117	  uint32_t idesc = _idesc_f16(BM, BN);
118	  if (warp_id == 0 && _elect_one()){
119	    _tc_fence();
120	    _tc_mma_f16(taddr, _smem_desc(A_smem, BM), _smem_desc(B_smem, BN), idesc, 0);
121	    _tc_commit(mbar_addr);
122	  }
123	  _mbar_wait(mbar_addr, 0);
124	  _tc_fence();
125	  for (int n = 0; n < BN / 8; n++){
126	    float t[8];
127	    const int addr = taddr + ((warp_id * 32) << 16) + (n * 8);
128	    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
129	                : "=f"(t[0]),"=f"(t[1]),"=f"(t[2]),"=f"(t[3]),
130	                  "=f"(t[4]),"=f"(t[5]),"=f"(t[6]),"=f"(t[7]) : "r"(addr));
131	    asm volatile("tcgen05.wait::ld.sync.aligned;");
132	    int row = warp_id * 32 + lane;
133	    #pragma unroll
134	    for (int i = 0; i < 8; i++) C[row * N + n * 8 + i] = t[i];
135	  }
136	  __syncthreads();
137	  if (warp_id == 0 && _elect_one()) _tc_dealloc(taddr, BN);
138	}
