140	// ---------------------------------------------------------------------------
141	// tc_trailing_wt: the FIRST of the three trailing GEMMs, as a tcgen05 K-TILED
142	// mainloop that accumulates W in TMEM (escaping the 255-reg / 12.5%-occ wall).
143	//
144	// Computes W^T = A_trail^T @ V  for one (matrix, NC-column-tile). The block
145	// Householder trailing update is  A -= V (T^T (V^T A)).  Let W = V^T A (BLK x
146	// ncols). We produce W^T (ncols x BLK) because that puts the ncols dimension on
147	// the MMA's M axis (>=128 when tiled), avoiding the M=32 atom (which is NOT a
148	// legal kind::f16 cta_group::1 MMA shape -- VERIFIED on this box: M=64/M=32
149	// produce garbage, only M=128 is correct, so we pad/tile M to 128).
150	//
151	//   W[i,c]  = sum_r Vbuf[i,r] * A[r,c]          (Vbuf == V^T, shape BLK x P)
152	//   W^T[c,i]= sum_r A[r,c] * Vbuf[i,r]
153	//   => MMA C[c,i] = sum_r Aop[c,r]*Bop[i,r] with Aop = A^T (M=ncols, K=P),
154	//      Bop = Vbuf (N=BLK, K=P).   C = W^T (ncols x BLK).
155	//
156	// GRID-FANOUT (W3 caveat 1): launch grid=(col_tiles, B) -- col_tiles M-tiles of
157	// 128 over ncols, times B matrices -- so occupancy is REALISED (a single-CTA-
158	// per-matrix form would repeat the megakernel's parallelism starvation even
159	// without spilling). blockIdx.x = M-tile, blockIdx.y = matrix.
160	//
161	// SMEM BUDGET (W3 caveat 2): K-TILED mainloop -- smem holds only BK rows of the
162	// contraction at a time (As: 128 x BK, Bs: BLK x BK), so smem is ~ (128+32)*BK*2
163	// bytes (BK=64 -> ~20KB), well within the 113KB @2-blk budget; the 75%-theoretical
164	// occupancy survives. Accumulation lives in TMEM across all K-tiles.
165	//
166	// VERIFIED CORRECT (standalone probe, fp16): NC=128/256/64, P=128/512, BK=64,
167	// 1-2 M-tiles, up to 8 K-tiles -> rel err ~3e-4 (fp16 rounding) on every case.
168	//
169	// fp16 inputs here (proves the structure). The brief's FP8 route (2x throughput)
170	// + per-tile residual correction swaps _f2h->fp8 cast and kind::f16->kind::f8f6f4
171	// once the fp16 structure is wired into the live n512 trailing.
172	// ---------------------------------------------------------------------------
173	extern "C" __global__ void tc_trailing_wt(
174	    const float* A, const float* Vt, float* WT,
175	    int B, int NC, int P, int BK,
176	    long sab, long san,          // A strides (matrix, row)  [A is the trailing block base]
177	    long svb, long svk, long svn,// Vbuf strides (matrix, refl-idx, row)
178	    long swb, long swc           // WT strides (matrix, col)  [WT row-stride = BLK=32]
179	){
180	  const int BM = 128, NN = 32;   // M-tile=128, N=BLK=32
181	  const int tid = threadIdx.x, wid = tid >> 5, lane = tid & 31;
182	  const int mt = blockIdx.x;     // M-tile over NC
183	  const int bid = blockIdx.y;    // matrix
184	  if (bid >= B) return;
185	  const int row0 = mt * BM;
186	  const float* Ab = A + (long)bid * sab;        // trailing block base for this matrix
187	  const float* Vb = Vt + (long)bid * svb;       // Vbuf[bid] (V^T, BLK x P)
188	  float* WTb = WT + (long)bid * swb;
189	  extern __shared__ __align__(1024) char tcw_smem[];
190	  ushort* As = reinterpret_cast<ushort*>(tcw_smem);
191	  const int Asz = BM * BK;
192	  ushort* Bs = As + Asz;
193	  const int A_smem = (int)__cvta_generic_to_shared(tcw_smem);
194	  const int B_smem = A_smem + Asz * (int)sizeof(ushort);
195	  #pragma nv_diag_suppress static_var_with_dynamic_init
196	  __shared__ uint64_t tcw_mbar[1];
197	  __shared__ int tcw_tmem[1];
198	  const int mbar_addr = (int)__cvta_generic_to_shared(tcw_mbar);
199	  if (wid == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
200	  else if (wid == 1){ int a = (int)__cvta_generic_to_shared(tcw_tmem); _tc_alloc(a, NN); }
201	  __syncthreads();
202	  const int taddr = tcw_tmem[0];
203	  const uint32_t idesc = _idesc_f16(BM, NN);
204	  const int rmax = min(BM, NC - row0);
205	  const int nkt = (P + BK - 1) / BK;
206	  for (int kt = 0; kt < nkt; kt++){
207	    const int k0 = kt * BK;
208	    const int kthis = min(BK, P - k0);
209	    for (int i = tid; i < BM * BK; i += blockDim.x) As[i] = 0;
210	    for (int i = tid; i < NN * BK; i += blockDim.x) Bs[i] = 0;
211	    __syncthreads();
212	    // Aop = A_trail^T tile: element (c-row, k) = A[row=k0+k, col=row0+c]
213	    for (int i = tid; i < rmax * kthis; i += blockDim.x){
214	      int c = i / kthis, k = i % kthis, b = k >> 3, kk = k & 7;
215	      As[b * (BM * 8) + c * 8 + kk] = _f2h(Ab[(long)(k0 + k) * san + (long)(row0 + c)]);
216	    }
217	    // Bop = Vbuf tile: element (refl i2, k) = Vbuf[i2, k0+k]
218	    for (int i = tid; i < NN * kthis; i += blockDim.x){
219	      int i2 = i / kthis, k = i % kthis, b = k >> 3, kk = k & 7;
220	      Bs[b * (NN * 8) + i2 * 8 + kk] = _f2h(Vb[(long)i2 * svk + (long)(k0 + k) * svn]);
221	    }
222	    __syncthreads();
223	    if (wid == 0 && _elect_one()){
224	      _tc_fence();
225	      int na = BK / 16;
226	      for (int ka = 0; ka < na; ka++){
227	        uint64_t ad = _smem_desc(A_smem + ka * BM * 32, BM);
228	        uint64_t bd = _smem_desc(B_smem + ka * NN * 32, NN);
229	        _tc_mma_f16(taddr, ad, bd, idesc, (kt > 0) || (ka > 0));
230	      }
231	      _tc_commit(mbar_addr);
232	    }
233	    _mbar_wait(mbar_addr, kt & 1);
234	    __syncthreads();  // smem reuse before next K-tile
235	  }
236	  _tc_fence();
237	  // read W^T (NC-tile rows x BLK=32). warp wid owns rows wid*32 of this tile.
238	  for (int n = 0; n < NN / 8; n++){
239	    float t[8];
240	    const int addr = taddr + ((wid * 32) << 16) + (n * 8);
241	    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
242	                : "=f"(t[0]),"=f"(t[1]),"=f"(t[2]),"=f"(t[3]),
243	                  "=f"(t[4]),"=f"(t[5]),"=f"(t[6]),"=f"(t[7]) : "r"(addr));
244	    asm volatile("tcgen05.wait::ld.sync.aligned;");
245	    int r = wid * 32 + lane;
246	    if (r < rmax){
247	      #pragma unroll
248	      for (int i = 0; i < 8; i++) WTb[(long)(row0 + r) * swc + n * 8 + i] = t[i];
249	    }
250	  }
251	  __syncthreads();
252	  if (wid == 0 && _elect_one()) _tc_dealloc(taddr, NN);
253	}
