// 64-bit shared-memory matrix descriptor, no-swizzle, K-major "contiguous
// blocks of (height, 8)" layout. LBO/SBO per PTX canonical layouts.
__device__ __forceinline__ uint64_t _desc_enc(uint64_t x){ return (x & 0x3FFFFULL) >> 4ULL; }
__device__ __forceinline__ uint64_t _smem_desc(int addr, int height){
  const int LBO = height * 16, SBO = 8 * 16;     // bytes
  return _desc_enc((uint64_t)addr) | (_desc_enc(LBO) << 16ULL)
       | (_desc_enc(SBO) << 32ULL) | (1ULL << 46ULL);
}

// mbarrier helpers (single-CTA, parity-phase wait).
__device__ __forceinline__ void _mbar_init(int mbar, int count){
  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(mbar), "r"(count));
  asm volatile("fence.mbarrier_init.release.cluster;");
}
__device__ __forceinline__ void _mbar_wait(int mbar, int phase){
  uint32_t ticks = 0x989680;
  asm volatile("{\n\t.reg .pred P1;\n\tLAB_W:\n\t"
               "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 P1, [%0], %1, %2;\n\t"
               "@P1 bra.uni LAB_D;\n\tbra.uni LAB_W;\n\tLAB_D:\n\t}"
               :: "r"(mbar), "r"(phase), "r"(ticks));
}

// tcgen05 ops (cta_group::1).
__device__ __forceinline__ void _tc_alloc(int smem_addr, int ncols){
  asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;"
               :: "r"(smem_addr), "r"(ncols));
}
__device__ __forceinline__ void _tc_dealloc(int taddr, int ncols){
  asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;"
               :: "r"(taddr), "r"(ncols));
}
__device__ __forceinline__ void _tc_relinquish(){
  asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
}
// one fp16 MMA atom (M from idesc, N from idesc, K=16). enable_d != 0 accumulates.
__device__ __forceinline__ void _tc_mma_f16(int taddr, uint64_t a_desc, uint64_t b_desc,
                                            uint32_t i_desc, int enable_d){
  asm volatile("{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %4, 0;\n\t"
               "tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, p;\n\t}"
               :: "r"(taddr), "l"(a_desc), "l"(b_desc), "r"(i_desc), "r"(enable_d));
}
__device__ __forceinline__ void _tc_commit(int mbar){
  asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];"
               :: "r"(mbar) : "memory");
}
__device__ __forceinline__ void _tc_fence(){ asm volatile("tcgen05.fence::after_thread_sync;"); }

// instruction descriptor for fp16 A/B, fp32 accumulate. M = MMA_M (64 or 128),
// N = MMA_N (mult of 8). a_format=0(f16) b_format=0(f16) c_format=1(f32).
__device__ __forceinline__ uint32_t _idesc_f16(int M, int N){
  return (1U << 4U) | ((uint32_t)N >> 3U << 17U) | ((uint32_t)M >> 4U << 24U);
